async function api(path,options={}){options.headers={...(options.headers||{}),...(authToken?{Authorization:`Bearer ${authToken}`}:{}),...(careAccessToken&&path.startsWith('/api/v1/care-network')?{'X-Care-Access':careAccessToken}:{})};let r=await fetch(path,options);if(r.status===401&&path!='/api/v1/auth/login'){$('#loginGate').classList.remove('hidden')}return r}
async function responseMessage(r,fallback){try{return (await r.json()).detail||fallback}catch{return fallback}}
function setUser(u){currentUser=u;let views=u.allowed_views||['account','about'],modules=u.allowed_modules||[],identity=`${u.full_name} · ${roleLabels[u.role]||u.role}`;$('#signedInUser').textContent=identity;$('#topSignedInUser').textContent=identity;$$('.nav').forEach(n=>n.classList.toggle('hidden',!views.includes(n.dataset.view)));$$('.module').forEach(m=>m.classList.toggle('hidden',!modules.includes(m.dataset.disease)));$$('#additionalModule option').forEach(o=>{if(o.value)o.hidden=!modules.includes(o.value)});if(modules.length&&!modules.includes(disease)){disease=modules[0];let button=$(`.module[data-disease="${disease}"]`);$$('.module').forEach(x=>x.classList.remove('selected'));if(button)button.classList.add('selected');else $('#additionalModule').value=disease;renderFields()}let active=$('.active-view')?.id;if(!views.includes(active)){let nav=$(`.nav[data-view="${views[0]}"]`);if(nav)setTimeout(()=>nav.click(),0)}renderAccount()}
function showGate(panel){['loginPanel','registerForm','forgotForm','passwordForm'].forEach(id=>$('#'+id).classList.toggle('hidden',id!==panel));$('#loginGate').classList.remove('hidden')}
async function restoreSession(){if(!authToken)return;try{let r=await api('/api/v1/auth/me');if(!r.ok){authToken='';sessionStorage.removeItem('healthsignal_token');return}let u=await r.json();setUser(u);if(u.password_change_required)showGate('passwordForm');else $('#loginGate').classList.add('hidden')}catch(e){sessionStorage.removeItem('healthsignal_token')}}
$('#loginForm').onsubmit=async e=>{e.preventDefault();$('#loginError').textContent='';try{let r=await fetch('/api/v1/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:$('#loginUser').value,password:$('#loginPassword').value})});if(!r.ok)throw Error(await responseMessage(r,'Sign in failed'));let x=await r.json();authToken=x.access_token;sessionStorage.setItem('healthsignal_token',authToken);setUser(x.user);if(x.user.password_change_required){$('#currentPassword').value=$('#loginPassword').value;showGate('passwordForm')}else $('#loginGate').classList.add('hidden');$('#loginPassword').value=''}catch(err){$('#loginError').textContent=err.message}};
