function renderFields(){ $('#clinicalFields').innerHTML=fields[disease]||'' };
function value(id){let e=$('#'+id);if(!e)return null;if(e.type==='checkbox')return e.checked;if(e.type==='number')return e.value===''?null:Number(e.value);return e.value}
function toast(msg){let t=$('#toast');t.textContent=msg;t.style.display='block';setTimeout(()=>t.style.display='none',2600)}
$$('.nav').forEach(b=>b.onclick=()=>{$$('.nav').forEach(x=>x.classList.remove('active'));b.classList.add('active');$$('.view').forEach(x=>x.classList.remove('active-view'));$('#'+b.dataset.view).classList.add('active-view');$('.sidebar').classList.remove('open');if(b.dataset.view==='care-network')prepareCareNetwork();if(b.dataset.view==='dashboard')loadDashboard();if(b.dataset.view==='surveillance')loadSurveillance();if(b.dataset.view==='records')loadRecords();if(b.dataset.view==='referrals')loadReferrals();if(b.dataset.view==='reviews')loadReviews();if(b.dataset.view==='users'){loadUsers();loadAudit()}if(b.dataset.view==='account')renderAccount()});
