$('#captureGps').onclick=()=>{if(!navigator.geolocation)return toast('GPS is unavailable on this device');if(!confirm('Capture this device location for this health encounter? Confirm that the client has consented.'))return;navigator.geolocation.getCurrentPosition(p=>{gps={latitude:p.coords.latitude,longitude:p.coords.longitude};$('#gpsMessage').textContent=`Location captured · accuracy ${Math.round(p.coords.accuracy)} m`},()=>toast('Location permission was not granted'),{enableHighAccuracy:true,timeout:12000})};
$('#patient_code').value='PT-'+crypto.randomUUID().slice(0,6).toUpperCase();$('#visit_date').value=new Date().toISOString().slice(0,10);renderFields();
$('#screenForm').onsubmit=async e=>{e.preventDefault();let payload={patient_code:value('patient_code'),visit_date:value('visit_date'),age:value('age'),sex:value('sex'),region:value('region'),district:value('district'),community:value('community'),facility:value('facility'),disease,symptoms:value('symptoms').split(',').map(x=>x.trim()).filter(Boolean),gps_consent:!!gps,...(gps||{})};['systolic_1','diastolic_1','systolic_2','diastolic_2','pulse','respiratory_rate','oxygen_saturation','weight_kg','height_cm','glucose_type','glucose_mmol_l','temperature_c','fever_or_history','malaria_test','malaria_result','pregnant','family_history','previous_diagnosis','cough_two_weeks','tb_contact','night_sweats','unexplained_weight_loss','lab_test_name','lab_result','lab_result_unit','outcome','follow_up_date','completion_status','case_status','notes','referred','referral_destination','referral_reason','gestational_age_weeks','gravida','parity','anc_visits','haemoglobin_g_dl','hiv_test_status','syphilis_test_status','previous_caesarean','multiple_pregnancy','reduced_fetal_movement','maternal_warning_signs','muac_cm','bilateral_oedema','feeding_problem','feeding_history','anaemia_symptoms','iron_folic_acid_status','pregnancy_malaria_status','test_offered','hiv_result_category','confirmation_status','linkage_status','stool_count_24h','diarrhoea_duration_days','dehydration_level','specimen_status','disease_test_result','rash_present','vaccination_status','symptom_onset_date','contact_history','neck_stiffness','altered_consciousness','breathing_difficulty','cough_present','hepatitis_exposure','jaundice_present','questionnaire_name','questionnaire_score','questionnaire_risk','functional_impairment','urgent_safety_concern','ncd_condition','ncd_measurement','ncd_unit','ncd_reported_priority'].forEach(k=>{let v=value(k);if(v!==null&&v!=='')payload[k]=v});if(disease==='acute_respiratory_infection'){payload.respiratory_rate=value('ari_respiratory_rate');payload.oxygen_saturation=value('ari_oxygen_saturation')}try{let r=await api('/api/v1/screenings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)throw Error(await responseMessage(r,'Could not save screening'));let x=await r.json(),color={Low:'#2b8a3e',Moderate:'#d87800',High:'#c63838',Urgent:'#862e9c'}[x.risk_level];await uploadSelectedFile(x.encounter_id);$('#result').innerHTML=`<div class="result-card" style="border-color:${color}"><span class="pill ${x.risk_level}">${x.risk_level} priority</span><h3>${h(x.classification)}</h3><p>${h(x.recommendation)}</p>${x.bmi?`<p><b>Calculated BMI:</b> ${x.bmi}</p>`:''}<small>${h(x.disclaimer)}</small></div>`;$('#result').scrollIntoView({behavior:'smooth'});toast('Encounter saved successfully');newPatientCode()}catch(err){if(!navigator.onLine){await queueEncounter(payload);toast('Offline: encounter queued securely on this device')}else toast(err.message||'Could not save screening')}};
function newPatientCode(){$('#patient_code').value='PT-'+crypto.randomUUID().slice(0,6).toUpperCase();gps=null;$('#gpsMessage').textContent='No location captured'}
async function uploadSelectedFile(encounterId){let file=$('#labAttachment').files[0];if(!file)return;if(!$('#fileConsent').checked)throw Error('Confirm consent before uploading the laboratory file');if(file.size>1_000_000)throw Error('File must be 1 MB or smaller on the free tier');let data=await new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});let r=await api(`/api/v1/encounters/${encounterId}/attachments`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({filename:file.name,content_type:file.type,data_base64:data,consent_confirmed:true})});if(!r.ok)throw Error(await responseMessage(r,'File upload failed'))}
async function loadDashboard(){try{let days=$('#days').value,r=await api('/api/v1/dashboard?days='+days),x=await r.json();$('#total').textContent=x.total_screenings;$('#high').textContent=x.high_or_urgent;$('#period').textContent=days+' days';let max=Math.max(1,...x.breakdown.map(a=>a.count));$('#bars').innerHTML=x.breakdown.length?x.breakdown.map(a=>`<div class="bar-row"><b>${a.disease}</b><span class="pill ${a.risk_level}">${a.risk_level}</span><div class="track"><div class="fill" style="width:${a.count/max*100}%"></div></div><b>${a.count}</b></div>`).join(''):'<p class="muted">No screening data recorded yet.</p>'}catch(e){toast('Dashboard unavailable')}}$('#days').onchange=loadDashboard;
async function loadRecords(){try{let r=await api('/api/v1/screenings?limit=500');records=await r.json();$('#recordRows').innerHTML=records.length?records.map(x=>`<tr><td>${h(x.visit_date)}</td><td><button class="code-link" data-code="${h(x.patient_code)}">${h(x.patient_code)}</button></td><td>${h(x.disease.replaceAll('_',' '))}</td><td>${h(x.case_status||'suspected')}</td><td><span class="pill ${h(x.risk_level)}">${h(x.risk_level)}</span></td><td>${h(x.classification)}</td><td>${h(x.district||'—')}</td></tr>`).join(''):'<tr><td colspan="7">No records yet.</td></tr>';$$('.code-link').forEach(b=>b.onclick=()=>{$('#patientSearch').value=b.dataset.code;searchPatient()})}catch(e){toast('Records unavailable')}}
$('#export').onclick=()=>{if(!records.length)return toast('No records to export');let keys=Object.keys(records[0]),csv=[keys.join(','),...records.map(r=>keys.map(k=>'"'+String(r[k]??'').replaceAll('"','""')+'"').join(','))].join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='healthsignal-screenings.csv';a.click()};

function renderAccount(){if(!currentUser)return;$('#accountProfile').innerHTML=`<h3>Account assignment</h3><div class="profile-grid"><div><span>Full name</span><b>${h(currentUser.full_name)}</b></div><div><span>Username</span><b>${h(currentUser.username)}</b></div><div><span>Professional workspace</span><b>${h(roleLabels[currentUser.role]||currentUser.role)}</b></div><div><span>Status</span><b>${h(currentUser.status)}</b></div><div><span>Facility</span><b>${h(currentUser.facility||'Not assigned')}</b></div><div><span>District</span><b>${h(currentUser.district||'Not assigned')}</b></div><div><span>Region</span><b>${h(currentUser.region||'Not assigned')}</b></div><div><span>Last sign in</span><b>${currentUser.last_login?new Date(currentUser.last_login).toLocaleString():'First session'}</b></div></div><h3>Assigned functions</h3><div class="flag-list">${(currentUser.allowed_views||[]).map(v=>`<span>${h(v.replaceAll('_',' '))}</span>`).join('')}</div>`}
$('#accountPasswordForm').onsubmit=async e=>{e.preventDefault();let m=$('#accountPasswordMessage'),r=await api('/api/v1/auth/change-password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({current_password:$('#accountCurrentPassword').value,new_password:$('#accountNewPassword').value})});m.className='form-message';m.textContent=r.ok?'Password changed successfully.':await responseMessage(r,'Password update failed');if(r.ok){m.classList.add('success');e.target.reset()}};
async function loadUsers(){let suffix=$('#userFilter').value?`?status=${$('#userFilter').value}`:'',r=await api('/api/v1/users'+suffix);if(!r.ok)return toast('User list unavailable');users=await r.json();let allResponse=await api('/api/v1/users'),all=allResponse.ok?await allResponse.json():users;$('#pendingUsers').textContent=all.filter(u=>u.status==='pending').length;$('#approvedUsers').textContent=all.filter(u=>u.status==='approved').length;$('#totalUsers').textContent=all.length;$('#userCards').innerHTML=users.length?users.map(u=>`<article class="user-card"><div><span class="account-status ${h(u.status)}">${h(u.status)}</span><h3>${h(u.full_name)}</h3><p>${h(u.username)} · ${h(u.email||'No email')}</p><small>Staff ID: ${h(u.staff_id||'—')} · ${h(u.phone||'—')}</small></div><div><b>${h(u.role.replaceAll('_',' '))}</b><p>${h(u.facility||'No facility')}</p><small>${h(u.district||'—')}, ${h(u.region||'—')}</small></div><div class="user-actions" data-user="${u.id}">${u.status!=='approved'?'<button class="approve" data-action="approved">Approve</button>':''}${u.status==='pending'?'<button class="reject" data-action="rejected">Reject</button>':''}${u.status==='approved'&&u.username!==currentUser.username?'<button class="suspend" data-action="suspended">Suspend</button>':''}${u.status==='suspended'?'<button class="approve" data-action="approved">Reactivate</button>':''}<button class="reset" data-action="assignment">Edit assignment</button><button class="reset" data-action="reset">Reset password</button></div></article>`).join(''):'<div class="card"><p class="muted">No accounts match this filter.</p></div>';$$('.user-actions button').forEach(b=>b.onclick=()=>userAction(Number(b.parentElement.dataset.user),b.dataset.action))}
async function userAction(id,action){let target=users.find(u=>u.id===id);if(!target)return;if(action==='reset'){let temporary=prompt(`Enter a temporary password for ${target.full_name}. It must have 12 characters, uppercase, lowercase and a number.`);if(!temporary)return;let r=await api(`/api/v1/users/${id}/reset-password`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({temporary_password:temporary})});return toast(r.ok?'Temporary password set':'Password reset failed')}if(action==='assignment'){let facility=prompt('Facility',target.facility||'');if(facility===null)return;let district=prompt('District',target.district||'');if(district===null)return;let region=prompt('Region',target.region||'');if(region===null)return;let role=prompt('Role: administrator, clinician, nutritionist_dietitian, disease_control_officer, field_officer or data_officer',target.role);if(role===null)return;let r=await api(`/api/v1/users/${id}/assignment`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({facility,district,region,role})});if(!r.ok)return toast(await responseMessage(r,'Assignment update failed'));toast('Assignment updated');loadUsers();loadAudit();return}if(!confirm(`${action[0].toUpperCase()+action.slice(1)} access for ${target.full_name}?`))return;let r=await api(`/api/v1/users/${id}/status`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:action,role:target.role})});if(!r.ok)return toast(await responseMessage(r,'Account update failed'));toast(`Account ${action}`);loadUsers();loadAudit()}
$('#userFilter').onchange=loadUsers;
async function loadAudit(){let r=await api('/api/v1/audit-logs?limit=50');if(!r.ok)return;let rows=await r.json();$('#auditList').innerHTML=rows.length?rows.map(x=>`<div class="audit-item"><b>${h(x.action.replaceAll('_',' '))}</b><span>${h(x.actor)} · ${h(x.details||x.target_type+' '+x.target_id)}</span><time>${new Date(x.created_at).toLocaleString()}</time></div>`).join(''):'<p class="muted">No security activity yet.</p>'}
