async function searchPatient(){let code=$('#patientSearch').value.trim();if(!code)return toast('Enter a patient code');let r=await api('/api/v1/patients/'+encodeURIComponent(code));if(!r.ok){$('#patientHistory').innerHTML='<div class="notice">Patient code not found.</div>';return}let x=await r.json();$('#patientHistory').innerHTML=`<div class="card history-card"><div class="section-title"><div><h3>${h(x.patient.patient_code)} · ${h(x.patient.sex)} · age ${h(x.patient.age)}</h3><p>${h(x.patient.community||'Community not recorded')}, ${h(x.patient.district||'District not recorded')}</p></div><span class="secure">${x.encounters.length} encounter${x.encounters.length===1?'':'s'}</span></div>${x.encounters.map(e=>`<article class="encounter"><div><b>${h(e.visit_date)}</b><span>${h(e.facility||'Field encounter')}</span></div><div><span>Vitals</span><b>${h(e.blood_pressure||'BP —')} · BMI ${h(e.bmi||'—')} · SpO₂ ${h(e.oxygen_saturation||'—')}</b></div><div><span>Outcome</span><b>${h(e.outcome||'Not completed')} · ${h(e.completion_status)}</b></div>${e.completion_status==='incomplete'?`<button class="secondary edit-encounter" data-id="${e.encounter_id}">Complete record</button>`:''}${['administrator','data_officer'].includes(currentUser.role)?`<button class="archive-button" data-id="${e.encounter_id}">Archive</button>`:''}</article>`).join('')}<h3>Laboratory results</h3>${x.laboratory_tests.length?x.laboratory_tests.map(l=>`<p>${h(l.test_name)}: <b>${h(l.result)} ${h(l.unit||'')}</b></p>`).join(''):'<p class="muted">No laboratory results recorded.</p>'}</div>`;$$('.edit-encounter').forEach(b=>b.onclick=()=>completeEncounter(b.dataset.id));$$('.archive-button').forEach(b=>b.onclick=()=>archiveEncounter(b.dataset.id))}
$('#searchPatient').onclick=searchPatient;
async function completeEncounter(id){let outcome=prompt('Enter the completed outcome');if(!outcome)return;let r=await api(`/api/v1/encounters/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({outcome,completion_status:'complete'})});if(r.ok){toast('Record completed');searchPatient()}else toast(await responseMessage(r,'Update failed'))}
async function archiveEncounter(id){if(!confirm('Archive this record? It will be retained but removed from active views.'))return;let r=await api(`/api/v1/encounters/${id}/archive`,{method:'POST'});if(r.ok){toast('Record archived');searchPatient();loadRecords()}else toast(await responseMessage(r,'Archive failed'))}

function miniBars(items){let max=Math.max(1,...items.map(x=>x.count));return items.slice(0,10).map(x=>`<div class="mini-bar"><span>${h(x.label.replaceAll('_',' '))}</span><i><b style="width:${x.count/max*100}%"></b></i><strong>${x.count}</strong></div>`).join('')||'<p class="muted">No data available.</p>'}
async function loadSurveillance(){let days=$('#surveillanceDays').value,district=$('#surveillanceDistrict').value.trim(),q=`?days=${days}${district?'&district='+encodeURIComponent(district):''}`,r=await api('/api/v1/surveillance/summary'+q);if(!r.ok)return toast(await responseMessage(r,'Surveillance data unavailable'));let x=await r.json();$('#surveillanceTotal').textContent=x.total;$('#positivity').textContent=x.test_positivity_rate===null?'—':x.test_positivity_rate+'%';$('#referralRate').textContent=x.referral_completion_rate===null?'—':x.referral_completion_rate+'%';$('#alertPanel').innerHTML=`<div class="alert ${x.alert.active?'active':''}"><b>${x.alert.active?'Investigation signal active':'No active statistical alert'}</b><span>${h(x.alert.message)} · Current week ${x.alert.current_week} · Baseline ${x.alert.four_week_average}</span></div>`;$('#diseaseCounts').innerHTML=miniBars(x.disease_counts);$('#demographics').innerHTML='<b>Age groups</b>'+miniBars(x.age_distribution)+'<b>Sex</b>'+miniBars(x.sex_distribution);renderTrend(x.weekly_trends);renderMap(x.hotspots);loadForecast(district)}
$('#loadSurveillance').onclick=loadSurveillance;
function renderTrend(rows){let max=Math.max(1,...rows.map(x=>x.count));$('#weeklyChart').innerHTML=rows.length?rows.slice(-16).map(x=>`<div class="trend-column" title="Week ${h(x.week)}: ${x.count}"><i style="height:${Math.max(5,x.count/max*150)}px"></i><small>${h(x.week.slice(5))}</small></div>`).join(''):'<p class="muted">Weekly trends will appear after records are submitted.</p>'}
function renderMap(hotspots){let points=hotspots.filter(x=>x.latitude&&x.longitude).map(x=>{let px=(x.longitude+3.3)/4.6*220+30,py=(11.2-x.latitude)/6.7*300+20;return `<circle cx="${px}" cy="${py}" r="${Math.min(15,5+x.count)}"><title>${h(x.community)}, ${h(x.district)}: ${x.count} high priority signals</title></circle>`}).join('');$('#hotspotMap').innerHTML=`<svg viewBox="0 0 280 360" role="img" aria-label="Interactive Ghana hotspot signal map"><path d="M70 25 L195 24 L220 68 L205 105 L235 155 L218 210 L245 257 L210 330 L142 345 L92 308 L55 248 L62 195 L35 148 L55 100 Z"></path>${points}</svg><div class="hotspot-list">${hotspots.slice(0,6).map(x=>`<span><b>${h(x.community)}</b> ${x.count} signals</span>`).join('')||'<span>No high priority hotspots.</span>'}</div>`}
async function loadForecast(district){let r=await api(`/api/v1/surveillance/forecast${district?'?district='+encodeURIComponent(district):''}`);if(!r.ok)return $('#forecastPanel').innerHTML='<p class="muted">Forecast is restricted for this role.</p>';let x=await r.json();if(x.status!=='available')return $('#forecastPanel').innerHTML=`<p>${h(x.message)}</p><small>Model ${h(x.model_version)} · ${h(x.last_training_date)}</small>`;$('#forecastPanel').innerHTML=`<span class="pill ${h(x.risk_level)}">${h(x.risk_level)} community risk</span><div class="forecast-values">${x.expected_cases_next_1_to_4_weeks.map((v,i)=>`<div><span>Week ${i+1}</span><b>${v}</b><small>upper ${x.upper_uncertainty_bounds[i]}</small></div>`).join('')}</div><p>${h(x.recommended_response)}</p><small>${h(x.disclaimer)} · Model ${h(x.model_version)} · trained ${h(x.last_training_date)}</small>`}
$('#downloadDistrict').onclick=async()=>{let district=$('#surveillanceDistrict').value.trim(),days=$('#surveillanceDays').value,r=await api(`/api/v1/reports/district.csv?days=${days}&district=${encodeURIComponent(district)}`);if(!r.ok)return toast('Report download unavailable');let a=document.createElement('a');a.href=URL.createObjectURL(await r.blob());a.download=`healthsignal-${district||'all'}-${days}d.csv`;a.click();URL.revokeObjectURL(a.href)};

async function loadReferrals(){let r=await api('/api/v1/referrals');if(!r.ok)return toast('Referrals unavailable');let rows=await r.json();$('#referralCards').innerHTML=rows.length?rows.map(x=>`<article class="user-card"><div><span class="account-status ${x.status==='Completed'?'approved':'pending'}">${h(x.status)}</span><h3>${h(x.patient_code)}</h3><p>${h(x.reason)}</p></div><div><b>${h(x.destination)}</b><p>Due ${h(x.due_date||'not set')}</p><small>Created by ${h(x.created_by)}</small></div><div class="user-actions">${x.status!=='Completed'?`<button class="approve complete-referral" data-id="${x.referral_id}">Mark completed</button>`:''}</div></article>`).join(''):'<div class="card"><p class="muted">No referrals recorded.</p></div>';$$('.complete-referral').forEach(b=>b.onclick=()=>completeReferral(b.dataset.id))}
$('#refreshReferrals').onclick=loadReferrals;
async function completeReferral(id){let r=await api(`/api/v1/referrals/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:'Completed'})});if(r.ok){toast('Referral completed');loadReferrals()}else toast(await responseMessage(r,'Update failed'))}

function reviewLabel(value){return h(String(value||'').replaceAll('_',' '))}
async function loadReviews(){let params=new URLSearchParams();[['status','#reviewStatus'],['priority','#reviewPriority'],['disease','#reviewDisease'],['district','#reviewDistrict']].forEach(([key,id])=>{let value=$(id).value.trim();if(value)params.set(key,value)});let r=await api('/api/v1/reviews'+(params.toString()?'?'+params:''));if(!r.ok)return toast(await responseMessage(r,'Clinical reviews unavailable'));let rows=await r.json();$('#reviewsAwaiting').textContent=rows.filter(x=>x.status==='awaiting_review').length;$('#reviewsUrgent').textContent=rows.filter(x=>['urgent','immediate'].includes(x.priority)&&x.status!=='closed').length;$('#reviewsFollowUp').textContent=rows.filter(x=>x.status==='follow_up_required').length;$('#reviewCards').innerHTML=rows.length?rows.map(x=>`<article class="card review-card"><div class="review-card-head"><div><span class="priority-badge ${h(x.priority)}">${reviewLabel(x.priority)}</span><h3>${h(x.patient_code)} · ${reviewLabel(x.disease)}</h3><p>${h(x.screening?.community||'Community not recorded')}, ${h(x.district||'District not recorded')} · ${h(x.screening?.visit_date||'')}</p></div><span class="review-status">${reviewLabel(x.status)}</span></div><div class="flag-list">${x.flag_reasons.map(reason=>`<span>${h(reason)}</span>`).join('')}</div><div class="review-summary"><span><small>Screening priority</small><b>${h(x.screening?.risk_level||'—')}</b></span><span><small>Case status</small><b>${h(x.screening?.case_status||'—')}</b></span><span><small>Assigned to</small><b>${h(x.assigned_to||'Unassigned')}</b></span><button class="primary open-review" data-id="${x.review_id}">Open review</button></div></article>`).join(''):'<div class="card"><p class="muted">No cases match these review filters.</p></div>';$$('.open-review').forEach(b=>b.onclick=()=>openReview(b.dataset.id))}
async function openReview(id){let r=await api('/api/v1/reviews/'+id);if(!r.ok)return toast(await responseMessage(r,'Review unavailable'));let x=await r.json(),canDecide=['administrator','clinician','nutritionist_dietitian','disease_control_officer'].includes(currentUser.role),canCheck=['administrator','data_officer'].includes(currentUser.role);$('#reviewDetail').innerHTML=`<span class="eyebrow">CLINICAL GOVERNANCE</span><h2 id="reviewModalTitle">${h(x.patient_code)} · ${reviewLabel(x.disease)}</h2><p>${h(x.screening.community||'—')}, ${h(x.district||'—')} · ${h(x.screening.visit_date)}</p><div class="flag-list">${x.flag_reasons.map(reason=>`<span>${h(reason)}</span>`).join('')}</div><div class="review-detail-grid"><div><small>Vitals</small><b>BP ${h(x.encounter.blood_pressure||'—')} · SpO₂ ${h(x.encounter.oxygen_saturation||'—')} · BMI ${h(x.encounter.bmi||'—')}</b></div><div><small>Symptoms</small><b>${h(x.encounter.symptoms.join(', ')||'Not recorded')}</b></div><div><small>Screening result</small><b>${h(x.screening.classification)}</b></div><div><small>Current outcome</small><b>${h(x.screening.outcome||'Not recorded')}</b></div></div>${canDecide?`<form id="reviewDecisionForm" class="review-form"><h3>Record clinical decision</h3><div class="grid four"><label>Classification<select id="reviewClassification"><option value="suspected">Suspected</option><option value="probable">Probable</option><option value="confirmed">Confirmed</option><option value="excluded">Excluded</option><option value="inconclusive">Inconclusive</option></select></label><label>Recommended action<select id="reviewAction"><option value="repeat_assessment">Repeat assessment</option><option value="request_laboratory_test">Request laboratory test</option><option value="refer_to_facility">Refer to facility</option><option value="notify_disease_control">Notify disease control officer</option><option value="start_follow_up">Start follow up</option><option value="close_case">Close case</option></select></label><label>Review status<select id="reviewDecisionStatus"><option value="under_review">Under review</option><option value="follow_up_required">Follow up required</option><option value="closed">Closed</option></select></label><label>Follow up date<input id="reviewFollowUp" type="date"></label></div><label>Reviewer notes<textarea id="reviewNotes" required minlength="5" maxlength="3000"></textarea></label><button class="primary" type="submit">Save accountable decision</button></form>`:''}${canCheck?`<form id="dataQualityForm" class="review-form"><h3>Data quality check</h3><label>Correction or validation note<textarea id="dataQualityNote" required minlength="5"></textarea></label><button class="secondary" type="submit">Record data quality check</button></form>`:''}<div class="review-history"><h3>Review history</h3>${x.history.length?x.history.map(e=>`<div><b>${reviewLabel(e.action)}</b><span>${h(e.actor)} · ${new Date(e.created_at).toLocaleString()}</span><p>${h(e.details)}</p></div>`).join(''):'<p class="muted">No review actions recorded.</p>'}</div>`;$('#reviewModal').classList.remove('hidden');if(canDecide)$('#reviewDecisionForm').onsubmit=e=>saveReview(e,id);if(canCheck)$('#dataQualityForm').onsubmit=e=>saveDataQuality(e,id)}
async function saveReview(e,id){e.preventDefault();let payload={classification:$('#reviewClassification').value,recommended_action:$('#reviewAction').value,status:$('#reviewDecisionStatus').value,follow_up_date:$('#reviewFollowUp').value||null,notes:$('#reviewNotes').value};let r=await api('/api/v1/reviews/'+id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)return toast(await responseMessage(r,'Could not save review'));toast('Clinical decision recorded');$('#reviewModal').classList.add('hidden');loadReviews()}
async function saveDataQuality(e,id){e.preventDefault();let r=await api(`/api/v1/reviews/${id}/data-quality`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({note:$('#dataQualityNote').value})});if(!r.ok)return toast(await responseMessage(r,'Could not save data quality note'));toast('Data quality check recorded');openReview(id);loadReviews()}
$('#applyReviewFilters').onclick=loadReviews;$('#refreshReviews').onclick=loadReviews;$('#closeReview').onclick=()=>$('#reviewModal').classList.add('hidden');$('#reviewModal').onclick=e=>{if(e.target.id==='reviewModal')e.currentTarget.classList.add('hidden')};

function openOfflineDb(){return new Promise((resolve,reject)=>{let request=indexedDB.open('healthsignal-field',1);request.onupgradeneeded=()=>request.result.createObjectStore('encounters',{keyPath:'offline_id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function queueEncounter(payload){let db=await openOfflineDb(),tx=db.transaction('encounters','readwrite');tx.objectStore('encounters').put({...payload,offline_id:crypto.randomUUID(),queued_at:new Date().toISOString()});await new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=reject});updateConnection()}
async function syncOffline(){if(!navigator.onLine||!authToken)return;let db=await openOfflineDb(),tx=db.transaction('encounters','readonly'),items=await new Promise((resolve,reject)=>{let r=tx.objectStore('encounters').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});for(let item of items){let offlineId=item.offline_id;delete item.offline_id;delete item.queued_at;let r=await api('/api/v1/screenings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(item)});if(r.ok){let del=db.transaction('encounters','readwrite');del.objectStore('encounters').delete(offlineId)}}updateConnection()}
async function updateConnection(){let count=0;try{let db=await openOfflineDb(),tx=db.transaction('encounters','readonly');count=await new Promise(resolve=>{let r=tx.objectStore('encounters').count();r.onsuccess=()=>resolve(r.result)})}catch{}$('#connectionStatus').textContent=navigator.onLine?'System online':'Offline field mode';$('#syncStatus').textContent=count?`${count} record${count===1?'':'s'} waiting to sync`:'All records synchronized'}
window.addEventListener('online',()=>{updateConnection();syncOffline()});window.addEventListener('offline',updateConnection);updateConnection();
if('serviceWorker' in navigator)navigator.serviceWorker.register('/static/service-worker.js');

let careEpisodes=[];
const careSelects=['triageEpisode','consultEpisode','labEpisode','medEpisode','referralEpisode','wardEpisode','ancEpisode','revenueEpisode'];
function setCareLock(locked,title,message,detail=''){let workspace=$('#careWorkspace');workspace.classList.toggle('locked',locked);workspace.setAttribute('aria-hidden',String(locked));$('#careSecurityPanel').classList.toggle('verified',!locked);$('#careSecurityTitle').textContent=title;$('#careSecurityMessage').textContent=message;$('#careSecurityDetail').textContent=detail;$('#verifyCareLocation').classList.toggle('hidden',!locked)}
async function prepareCareNetwork(){let r=await api('/api/v1/care-network/security');if(!r.ok)return toast(await responseMessage(r,'Could not check Care Network security'));let x=await r.json();$('#geofenceConfigForm').classList.toggle('hidden',!x.administrator);$('#geofenceFacility').value=x.facility;$('#geofenceRadius').value=String(x.allowed_radius_m||250);$('#geofenceEnabled').checked=x.geofence_enabled;if(!x.geofence_enabled){setCareLock(false,'Care Network available',`Location restriction is not enabled for ${x.facility}.`,x.notice);return loadCareNetwork()}if(careAccessToken){let check=await api('/api/v1/care-network/overview');if(check.ok){setCareLock(false,'Workplace location verified',`${x.facility} · secure Care Network session active.`,`Location authorization lasts ${x.grant_minutes} minutes.`);return loadCareNetwork()}careAccessToken='';sessionStorage.removeItem('healthsignal_care_access')}setCareLock(true,'Workplace verification required',`Verify that this device is inside the approved area for ${x.facility}.`,`Allowed radius: ${x.allowed_radius_m} metres · Location permission is required.`)}
function deviceLocation(){return new Promise((resolve,reject)=>{if(!navigator.geolocation)return reject(Error('Location is unavailable on this device'));navigator.geolocation.getCurrentPosition(resolve,err=>reject(Error(err.code===1?'Location permission was denied':'A reliable location could not be obtained')),{enableHighAccuracy:true,timeout:15000,maximumAge:0})})}
$('#verifyCareLocation').onclick=async()=>{let button=$('#verifyCareLocation');button.disabled=true;button.textContent='Checking location…';try{let position=await deviceLocation(),payload={latitude:position.coords.latitude,longitude:position.coords.longitude,accuracy_m:position.coords.accuracy},r=await api('/api/v1/care-network/security/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)throw Error(await responseMessage(r,'Workplace location could not be verified'));let x=await r.json();if(x.care_access_token){careAccessToken=x.care_access_token;sessionStorage.setItem('healthsignal_care_access',careAccessToken)}setCareLock(false,'Workplace location verified',x.restricted?`${x.facility} · ${Math.round(x.distance_m)} metres from the registered point.`:x.message,x.restricted?`Access expires at ${new Date(x.expires_at).toLocaleTimeString()}.`:'Geofencing can be configured by an administrator.');loadCareNetwork()}catch(error){setCareLock(true,'Access not granted',error.message,'Care Network remains locked. Field Screening and approved public health functions are still available.')}finally{button.disabled=false;button.textContent='Verify workplace location'}};
$('#captureFacilityLocation').onclick=async()=>{let button=$('#captureFacilityLocation');button.disabled=true;button.textContent='Capturing…';try{let position=await deviceLocation();$('#geofenceLatitude').value=position.coords.latitude.toFixed(7);$('#geofenceLongitude').value=position.coords.longitude.toFixed(7);$('#geofenceMessage').textContent=`Location captured with approximately ${Math.round(position.coords.accuracy)} metre accuracy.`;$('#geofenceMessage').classList.add('success')}catch(error){toast(error.message)}finally{button.disabled=false;button.textContent='Capture this location'}};
$('#geofenceConfigForm').onsubmit=async e=>{e.preventDefault();let payload={facility:$('#geofenceFacility').value,latitude:Number($('#geofenceLatitude').value),longitude:Number($('#geofenceLongitude').value),allowed_radius_m:Number($('#geofenceRadius').value),geofence_enabled:$('#geofenceEnabled').checked},r=await api('/api/v1/care-network/security/config',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)return toast(await responseMessage(r,'Could not save facility security'));careAccessToken='';sessionStorage.removeItem('healthsignal_care_access');$('#geofenceMessage').textContent='Facility security saved.';$('#geofenceMessage').classList.add('success');toast('Facility geofence updated');prepareCareNetwork()};
function careEpisodeOptions(rows){return '<option value="">Select a patient journey</option>'+rows.map(x=>`<option value="${h(x.episode_id)}">${h(x.patient_code)} · ${h(x.assigned_department)} · ${h(x.visit_date)}</option>`).join('')}
function fillCareSelects(){let options=careEpisodeOptions(careEpisodes);careSelects.forEach(id=>{let el=$('#'+id);if(el)el.innerHTML=options})}
function careStatus(value){return h(String(value||'').replaceAll('_',' '))}
function configureCareWorkspace(){if(!currentUser)return;let role=currentUser.role,all=['administrator','clinician','nutritionist_dietitian','opd_nurse','records_officer','laboratory_officer','pharmacist','ward_nurse','midwife','theatre_staff','stores_officer','revenue_officer','accountant','insurance_officer'],permissions={careOverview:all,careRecords:['administrator','records_officer'],careOpd:['administrator','opd_nurse'],careConsultation:['administrator','clinician','nutritionist_dietitian'],careLaboratory:['administrator','laboratory_officer'],carePharmacy:['administrator','clinician','nutritionist_dietitian','pharmacist'],careWards:['administrator','clinician','ward_nurse','midwife','theatre_staff'],careAnc:['administrator','clinician','midwife','nutritionist_dietitian'],careStores:['administrator','stores_officer','pharmacist','accountant'],careRevenue:['administrator','revenue_officer'],careAccounts:['administrator','accountant'],careInsurance:['administrator','records_officer','insurance_officer','accountant'],careReferral:['administrator','clinician','nutritionist_dietitian']};$$('.care-tab').forEach(tab=>tab.classList.toggle('hidden',!(permissions[tab.dataset.carePanel]||[]).includes(role)));let formAccess={episodeForm:['administrator','records_officer'],triageForm:['administrator','opd_nurse'],consultForm:['administrator','clinician','nutritionist_dietitian'],careLabForm:['administrator','laboratory_officer'],medicationForm:['administrator','clinician','nutritionist_dietitian'],wardAdmissionForm:['administrator','clinician','ward_nurse','midwife','theatre_staff'],ancForm:['administrator','clinician','midwife','nutritionist_dietitian'],inventoryForm:['administrator','stores_officer'],revenueForm:['administrator','revenue_officer'],insuranceClaimForm:['administrator','insurance_officer'],networkReferralForm:['administrator','clinician','nutritionist_dietitian']};Object.entries(formAccess).forEach(([id,roles])=>$('#'+id).classList.toggle('role-disabled',!roles.includes(role)));$('#pharmacyQueueCard').classList.toggle('hidden',!['administrator','pharmacist'].includes(role));$$('#care-network .role-disabled input,#care-network .role-disabled select,#care-network .role-disabled textarea,#care-network .role-disabled button').forEach(el=>el.disabled=true);$$('#care-network form:not(.role-disabled) input,#care-network form:not(.role-disabled) select,#care-network form:not(.role-disabled) textarea,#care-network form:not(.role-disabled) button').forEach(el=>el.disabled=false);let activeTab=$('.care-tab.active:not(.hidden)');if(!activeTab){let first=$('.care-tab:not(.hidden)');if(first)first.click()}}
async function loadCareNetwork(){configureCareWorkspace();let r=await api('/api/v1/care-network/overview');if(!r.ok)return toast(await responseMessage(r,'Care Network is unavailable'));let x=await r.json();$('#careActive').textContent=x.active_episodes;$('#careIncoming').textContent=x.incoming_referrals;$('#careOpenReferrals').textContent=x.open_referrals;$('#departmentQueues').innerHTML=x.department_queues.length?x.department_queues.map(q=>`<button class="department-card" data-department="${h(q.department)}"><span>${h(q.department)}</span><b>${q.count}</b><small>waiting</small></button>`).join(''):'<p class="muted">No active queues at ${h(x.facility)}.</p>';$('#recentEpisodes').innerHTML=x.recent_episodes.length?x.recent_episodes.map(e=>`<button class="journey-row" data-episode="${h(e.episode_id)}"><span><b>${h(e.patient_code)}</b><small>${h(e.visit_date)} · ${h(e.visit_type)}</small></span><i>${h(e.assigned_department)}</i><em>${careStatus(e.status)}</em></button>`).join(''):'<p class="muted">No patient journeys are waiting in your workspace.</p>';let er=await api('/api/v1/care-network/episodes');if(er.ok){careEpisodes=await er.json();fillCareSelects()}let role=currentUser.role;if(['administrator','clinician','nutritionist_dietitian'].includes(role)){loadFacilities();loadNetworkReferrals()}if(['administrator','pharmacist'].includes(role))loadMedicationQueue();if(['administrator','clinician','ward_nurse','midwife','theatre_staff'].includes(role))loadWards();if(['administrator','clinician','midwife','nutritionist_dietitian'].includes(role))loadAnc();if(['administrator','stores_officer','pharmacist','accountant'].includes(role))loadInventory();if(['administrator','revenue_officer','accountant'].includes(role))loadRevenue();if(['administrator','accountant'].includes(role))loadAccounts();if(['administrator','records_officer','insurance_officer','accountant'].includes(role))loadInsuranceClaims()}
$('#refreshCare').onclick=loadCareNetwork;
$$('.care-tab').forEach(tab=>tab.onclick=()=>{$$('.care-tab').forEach(x=>x.classList.remove('active'));tab.classList.add('active');$$('.care-panel').forEach(x=>x.classList.remove('active'));$('#'+tab.dataset.carePanel).classList.add('active')});
async function loadFacilities(){let r=await api('/api/v1/care-network/facilities');if(!r.ok)return;let rows=await r.json();$('#facilityOptions').innerHTML=rows.map(x=>`<option value="${h(x.name)}">${h(x.district||x.facility_type)}</option>`).join('')}
$('#episodeForm').onsubmit=async e=>{e.preventDefault();let insured=$('#careInsured').checked,payload={patient_code:$('#carePatientCode').value,age:Number($('#careAge').value),sex:$('#careSex').value,community:$('#careCommunity').value,visit_type:$('#careVisitType').value,chief_complaint:$('#careComplaint').value,insurance_number:insured?$('#careInsuranceNumber').value:'',ccc_number:insured?$('#careCccNumber').value:'',surname:insured?$('#careSurname').value:'',other_names:insured?$('#careOtherNames').value:'',date_of_birth:insured?$('#careDob').value:'',folder_number:insured?$('#careFolderNumber').value:'',attendance_type:insured?$('#careAttendanceType').value:''};let r=await api('/api/v1/care-network/episodes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)return toast(await responseMessage(r,'Could not register visit'));let x=await r.json();$('#episodeResult').innerHTML=`<b>${h(x.patient_code)}</b> registered. Care episode ${h(x.episode_id.slice(0,8))}.${x.insurance_claim_created?' Insurance claim draft opened.':''}`;$('#episodeResult').classList.add('success');e.target.reset();$('#insuranceRegistrationFields').classList.add('hidden');toast(x.insurance_claim_created?'Patient sent to OPD and claim draft created':'Patient sent to OPD queue');loadCareNetwork()};
$('#triageForm').onsubmit=async e=>{e.preventDefault();let id=$('#triageEpisode').value,payload={temperature_c:value('triageTemp'),pulse:value('triagePulse'),respiratory_rate:value('triageResp'),oxygen_saturation:value('triageSpo2'),systolic:value('triageSys'),diastolic:value('triageDia'),weight_kg:value('triageWeight'),height_cm:value('triageHeight'),notes:value('triageNotes')};let r=await api(`/api/v1/care-network/episodes/${id}/triage`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)return toast(await responseMessage(r,'Could not save triage'));toast('Triage saved and patient sent to consultation');e.target.reset();loadCareNetwork()};
$('#consultForm').onsubmit=async e=>{e.preventDefault();let id=$('#consultEpisode').value,payload={assessment:$('#consultAssessment').value,plan:$('#consultPlan').value,allergies:$('#consultAllergies').value,disposition:$('#consultDisposition').value};let r=await api(`/api/v1/care-network/episodes/${id}/consultation`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)return toast(await responseMessage(r,'Could not save consultation'));toast('Consultation saved');e.target.reset();loadCareNetwork()};
$('#careLabForm').onsubmit=async e=>{e.preventDefault();let id=$('#labEpisode').value,payload={test_name:$('#careLabName').value,result:$('#careLabResult').value,unit:$('#careLabUnit').value,next_department:'Consulting Room'};let r=await api(`/api/v1/care-network/episodes/${id}/laboratory`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)return toast(await responseMessage(r,'Could not save laboratory result'));toast('Result released to Consulting Room');e.target.reset();loadCareNetwork()};
$('#medicationForm').onsubmit=async e=>{e.preventDefault();let id=$('#medEpisode').value,payload={medicine:$('#medicineName').value,instructions:$('#medicineInstructions').value};let r=await api(`/api/v1/care-network/episodes/${id}/medications`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)return toast(await responseMessage(r,'Could not create prescription'));toast('Prescription sent to pharmacy');e.target.reset();loadCareNetwork()};
async function loadMedicationQueue(){let r=await api('/api/v1/care-network/medications');if(!r.ok)return;let rows=await r.json();$('#medicationQueue').innerHTML=rows.filter(x=>x.status==='prescribed').slice(0,5).map(x=>`<div><span><b>${h(x.patient_code)}</b><small>${h(x.medicine)} · ${h(x.instructions)}</small></span><button class="dispense-med" data-id="${h(x.order_id)}">Dispense</button></div>`).join('')||'<p class="muted">No prescriptions waiting.</p>';$$('.dispense-med').forEach(b=>b.onclick=()=>dispenseMedication(b.dataset.id))}
async function dispenseMedication(id){let r=await api(`/api/v1/care-network/medications/${id}/dispense`,{method:'PATCH'});if(!r.ok)return toast(await responseMessage(r,'Could not dispense medicine'));toast('Medicine dispensed and visit completed');loadCareNetwork()}
async function loadWards(){let r=await api('/api/v1/care-network/wards');if(!r.ok)return;let x=await r.json();$('#wardOccupancy').innerHTML=x.wards.map(w=>`<div class="ward-tile"><span>${h(w.ward)}</span><b>${w.occupied}</b><small>admitted</small></div>`).join('');$('#wardAdmissions').innerHTML=x.admissions.length?x.admissions.map(a=>`<div><span><b>${h(a.patient_code)} · ${h(a.ward)}</b><small>${h(a.bed_number||'Bed pending')} · ${h(a.reason)}</small></span>${currentUser.role==='theatre_staff'?'':`<button class="discharge-patient" data-id="${h(a.admission_id)}">Discharge</button>`}</div>`).join(''):'<p class="muted">No active ward admissions.</p>';$$('.discharge-patient').forEach(b=>b.onclick=()=>dischargePatient(b.dataset.id))}
$('#wardAdmissionForm').onsubmit=async e=>{e.preventDefault();let payload={episode_id:$('#wardEpisode').value,ward:$('#wardSelect').value,bed_number:$('#wardBed').value,admission_reason:$('#wardReason').value},r=await api('/api/v1/care-network/wards/admissions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)return toast(await responseMessage(r,'Could not admit patient'));toast('Patient admitted to ward');e.target.reset();loadCareNetwork()};
async function dischargePatient(id){let summary=prompt('Enter the discharge or transfer summary');if(!summary)return;let r=await api(`/api/v1/care-network/wards/admissions/${id}/discharge`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({discharge_summary:summary})});if(!r.ok)return toast(await responseMessage(r,'Could not discharge patient'));toast('Ward discharge recorded');loadCareNetwork()}
function bloodPressure(text){let parts=String(text||'').split('/').map(Number);return parts.length===2&&parts.every(Number.isFinite)?parts:[null,null]}
async function loadAnc(){let r=await api('/api/v1/care-network/anc');if(!r.ok)return;let rows=await r.json();$('#ancVisits').innerHTML=rows.length?rows.map(x=>`<div><span><b>${h(x.patient_code)}</b><small>${h(x.gestational_age_weeks??'—')} weeks · BP ${h(x.blood_pressure||'—')} · next ${h(x.next_visit_date||'not set')}</small></span></div>`).join(''):'<p class="muted">No ANC visits recorded.</p>'}
$('#ancForm').onsubmit=async e=>{e.preventDefault();let [systolic,diastolic]=bloodPressure($('#ancBp').value),payload={episode_id:$('#ancEpisode').value,gestational_age_weeks:value('ancGestation'),gravida:value('ancGravida'),parity:value('ancParity'),systolic,diastolic,haemoglobin_g_dl:value('ancHb'),fetal_heart_rate:value('ancFhr'),danger_signs:$('#ancDangerSigns').value,plan:$('#ancPlan').value,next_visit_date:$('#ancNextVisit').value},r=await api('/api/v1/care-network/anc',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)return toast(await responseMessage(r,'Could not save ANC visit'));toast('ANC visit recorded');e.target.reset();loadCareNetwork()};
async function loadInventory(){let r=await api('/api/v1/care-network/stores');if(!r.ok)return;let rows=await r.json();$('#inventoryList').innerHTML=rows.length?rows.map(x=>`<div class="${x.low_stock?'low-stock':''}"><span><b>${h(x.item_name)}</b><small>${h(x.category)} · ${x.quantity} ${h(x.unit)} · reorder at ${x.reorder_level}${x.low_stock?' · LOW STOCK':''}</small></span></div>`).join(''):'<p class="muted">No inventory items recorded.</p>'}
$('#inventoryForm').onsubmit=async e=>{e.preventDefault();let payload={item_name:$('#inventoryName').value,category:$('#inventoryCategory').value,quantity:Number($('#inventoryQuantity').value),reorder_level:Number($('#inventoryReorder').value),unit:$('#inventoryUnit').value,batch_number:$('#inventoryBatch').value,expiry_date:$('#inventoryExpiry').value},r=await api('/api/v1/care-network/stores',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)return toast(await responseMessage(r,'Could not save inventory'));toast('Inventory item saved');e.target.reset();loadInventory()};
async function loadRevenue(){let r=await api('/api/v1/care-network/finance/transactions');if(!r.ok)return;let rows=await r.json();$('#revenueTransactions').innerHTML=rows.length?rows.slice(0,30).map(x=>`<div><span><b>${h(x.receipt_number)} · GHS ${Number(x.amount).toFixed(2)}</b><small>${h(x.service)} · ${h(x.payment_method)} · ${h(x.patient_code||'walk-in')}</small></span></div>`).join(''):'<p class="muted">No revenue transactions recorded.</p>'}
$('#revenueForm').onsubmit=async e=>{e.preventDefault();let selected=careEpisodes.find(x=>x.episode_id===$('#revenueEpisode').value),payload={episode_id:$('#revenueEpisode').value||null,patient_code:selected?.patient_code||$('#revenuePatientCode').value,service:$('#revenueService').value,amount:Number($('#revenueAmount').value),payment_method:$('#revenueMethod').value,notes:$('#revenueNotes').value},r=await api('/api/v1/care-network/finance/transactions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)return toast(await responseMessage(r,'Could not record payment'));let x=await r.json();$('#revenueReceipt').innerHTML=`<div class="access-code"><span>Receipt issued</span><b>${h(x.receipt_number)}</b><small>GHS ${Number(x.amount).toFixed(2)}</small></div>`;toast('Payment and receipt recorded');e.target.reset();loadRevenue()};
async function loadAccounts(){let r=await api('/api/v1/care-network/finance/summary');if(!r.ok)return;let x=await r.json();$('#accountTransactionCount').textContent=x.transaction_count;$('#accountRevenueTotal').textContent=`GHS ${Number(x.total_revenue).toFixed(2)}`;$('#accountPaymentBreakdown').innerHTML=x.by_payment_method.length?x.by_payment_method.map(m=>`<div class="department-card"><span>${h(m.method)}</span><b>GHS ${Number(m.amount).toFixed(2)}</b><small>collected</small></div>`).join(''):'<p class="muted">No paid transactions to summarize.</p>'}
let currentClaimEntries=[];
async function loadInsuranceClaims(){let r=await api('/api/v1/care-network/insurance/claims');if(!r.ok)return;let rows=await r.json();$('#insuranceClaimList').innerHTML=rows.length?rows.map(x=>`<button class="claim-row" data-id="${h(x.claim_id)}"><span><b>${h(x.patient_code)}</b><small>HIN ${h(x.member_number)} · CCC ${h(x.ccc_number||'pending')}</small></span><em class="claim-status ${h(x.status)}">${careStatus(x.status)}</em></button>`).join(''):'<p class="muted">No insurance claim drafts. Records creates one automatically when a Member/HIN number is entered.</p>';$$('.claim-row').forEach(b=>b.onclick=()=>openInsuranceClaim(b.dataset.id))}
function claimEntryCards(title,rows){return `<section><h4>${h(title)} <span>${rows.length}</span></h4>${rows.length?rows.map(x=>`<p><b>${h(x.code||x.description||'Entry')}</b>${x.description&&x.code?` · ${h(x.description)}`:''}${x.result?` · ${h(x.result)} ${h(x.unit||'')}`:''}</p>`).join(''):'<p class="muted">None recorded yet.</p>'}</section>`}
async function openInsuranceClaim(id){let r=await api(`/api/v1/care-network/insurance/claims/${id}`);if(!r.ok)return toast(await responseMessage(r,'Could not open claim'));let x=await r.json();$('#insuranceClaimForm').classList.remove('hidden');$('#insuranceClaimTitle').textContent=`${x.patient_code} · ${careStatus(x.status)}`;let values={insuranceClaimId:x.claim_id,claimMemberNumber:x.member_number,claimCccNumber:x.ccc_number,claimSurname:x.surname,claimOtherNames:x.other_names,claimGender:x.gender,claimDob:x.date_of_birth,claimFolder:x.folder_number,claimAttendance:x.attendance_type,claimOutcome:x.service_outcome,claimSpecialty:x.specialty,claimPhysician:x.physician_name_id,claimPreauth:x.pre_authorization_codes,claimGdrg:x.principal_gdrg,claimReferringFacility:x.referring_facility,claimReferralCode:x.referral_code};Object.entries(values).forEach(([id,v])=>$('#'+id).value=v||'');let automatic={Procedures:x.procedures.filter(e=>e.source!=='Insurance desk'),Diagnoses:x.diagnoses.filter(e=>e.source!=='Insurance desk'),Investigations:x.investigations.filter(e=>e.source!=='Insurance desk'),Medicines:x.medicines.filter(e=>e.source!=='Insurance desk')};$('#claimAutoEntries').innerHTML=`<div class="claim-summary"><span>Services: ${x.service_types.map(h).join(' · ')}</span><span>Dates: ${x.service_dates.map(h).join(' · ')||'Awaiting service activity'}</span></div>`+Object.entries(automatic).map(([title,rows])=>claimEntryCards(title,rows)).join('');currentClaimEntries=[...x.procedures,...x.diagnoses,...x.investigations,...x.medicines].filter(e=>e.source==='Insurance desk').map(e=>({...e,type:e.type||'diagnosis'}));renderManualClaimEntries();renderClaimValidation(x.validation_errors);$('#insuranceClaimForm').scrollIntoView({behavior:'smooth',block:'start'})}
function renderManualClaimEntries(){$('#claimManualEntries').innerHTML=currentClaimEntries.length?currentClaimEntries.map((x,i)=>`<div><span><b>${h(careStatus(x.type))}: ${h(x.description)}</b><small>${h(x.code||'No code')} · qty ${h(x.quantity||1)}${x.unit_cost?` · GHS ${Number(x.unit_cost).toFixed(2)}`:''}</small></span><button type="button" data-index="${i}" class="remove-claim-entry">Remove</button></div>`).join(''):'<p class="muted">No manual entries. Clinical services remain automatically linked.</p>';$$('.remove-claim-entry').forEach(b=>b.onclick=()=>{currentClaimEntries.splice(Number(b.dataset.index),1);renderManualClaimEntries()})}
function renderClaimValidation(errors=[]){$('#claimValidation').innerHTML=errors.length?`<div class="claim-errors"><b>Claim needs correction</b><ul>${errors.map(e=>`<li>${h(e)}</li>`).join('')}</ul></div>`:'<div class="claim-ready">No outstanding validation errors.</div>'}
$('#addClaimEntry').onclick=()=>{let description=$('#claimEntryDescription').value.trim();if(!description)return toast('Enter a claim entry description');currentClaimEntries.push({type:$('#claimEntryType').value,code:$('#claimEntryCode').value,description,quantity:value('claimEntryQuantity')||1,unit_cost:value('claimEntryCost'),source:'Insurance desk'});['claimEntryCode','claimEntryDescription','claimEntryQuantity','claimEntryCost'].forEach(id=>$('#'+id).value='');renderManualClaimEntries()};
function claimPayload(){return {member_number:$('#claimMemberNumber').value,ccc_number:$('#claimCccNumber').value,surname:$('#claimSurname').value,other_names:$('#claimOtherNames').value,gender:$('#claimGender').value,date_of_birth:$('#claimDob').value,folder_number:$('#claimFolder').value,attendance_type:$('#claimAttendance').value,service_outcome:$('#claimOutcome').value,specialty:$('#claimSpecialty').value,physician_name_id:$('#claimPhysician').value,pre_authorization_codes:$('#claimPreauth').value,principal_gdrg:$('#claimGdrg').value,referring_facility:$('#claimReferringFacility').value,referral_code:$('#claimReferralCode').value,manual_entries:currentClaimEntries}}
$('#insuranceClaimForm').onsubmit=async e=>{e.preventDefault();let id=$('#insuranceClaimId').value,r=await api(`/api/v1/care-network/insurance/claims/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(claimPayload())});if(!r.ok)return toast(await responseMessage(r,'Could not save claim'));toast('Insurance claim draft saved');openInsuranceClaim(id);loadInsuranceClaims()};
$('#validateClaim').onclick=async()=>{let id=$('#insuranceClaimId').value,save=await api(`/api/v1/care-network/insurance/claims/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(claimPayload())});if(!save.ok)return toast(await responseMessage(save,'Could not save claim'));let r=await api(`/api/v1/care-network/insurance/claims/${id}/validate`,{method:'POST'}),x=await r.json();renderClaimValidation(x.errors||[]);toast(x.errors?.length?'Claim requires correction':'Claim is ready for XML export');loadInsuranceClaims()};
$('#exportClaimXml').onclick=async()=>{let id=$('#insuranceClaimId').value,r=await api(`/api/v1/care-network/insurance/claims/${id}/xml`);if(!r.ok)return toast(await responseMessage(r,'XML export unavailable'));let blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`healthsignal-claim-${id.slice(0,8)}.xml`;a.click();URL.revokeObjectURL(url);toast('XML claim draft exported')};
$('#refreshInsurance').onclick=loadInsuranceClaims;
$('#networkReferralForm').onsubmit=async e=>{e.preventDefault();let payload={episode_id:$('#referralEpisode').value,destination_facility:$('#destinationFacility').value,receiving_department:$('#receivingDepartment').value,validity_hours:Number($('#referralValidity').value),reason:$('#networkReferralReason').value,clinical_summary:$('#clinicalSummary').value,urgency:$('#referralUrgency').value,consent_type:$('#referralConsentType').value,consent_scopes:$$('.referral-scope:checked').map(x=>x.value),consent_confirmed:$('#referralConsent').checked};let r=await api('/api/v1/care-network/referrals',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)return toast(await responseMessage(r,'Could not create referral'));let x=await r.json();$('#referralCodeResult').innerHTML=`<div class="access-code"><span>Time limited referral code</span><b>${h(x.access_code)}</b><small>${h(x.access_code_notice)}</small><small>Shared: ${x.consent_scopes.map(h).join(', ')}</small></div>`;toast('Patient-authorized referral created');loadCareNetwork()};
function referralPacketHtml(x){let list=(title,rows,render)=>rows&&rows.length?`<h4>${h(title)}</h4>${rows.map(render).join('')}`:'';return `<div class="shared-record ${x.emergency_access?'emergency-record':''}"><div class="section-title"><div><span class="eyebrow">${x.emergency_access?'EMERGENCY MINIMUM DATA':'AUTHORIZED REFERRAL PACKAGE'}</span><h3>${h(x.patient.patient_code)}</h3><p>${x.patient.sex?`${h(x.patient.sex)} · age ${h(x.patient.age||'—')}`:'Demographics not authorized for this referral'}</p></div><span class="priority-badge ${h(x.referral.urgency)}">${h(x.referral.urgency)}</span></div><div class="scope-strip">Shared only: ${x.shared_scopes.map(h).join(' · ')}</div><b>Reason for referral</b><p>${h(x.referral.reason)}</p>${x.referral.clinical_summary?`<b>Clinical handover</b><p>${h(x.referral.clinical_summary)}</p>`:''}${list('Allergies',x.allergies,a=>`<p>${h(a)}</p>`)}${list('Latest vital signs',x.vitals,v=>`<p>${h(v.summary)}</p>`)}${list('Relevant laboratory results',x.laboratory_results,l=>`<p><b>${h(l.test_name)}</b>: ${h(l.result)} ${h(l.unit||'')}</p>`)}${list('Current medicines',x.medications,m=>`<p><b>${h(m.medicine)}</b>: ${h(m.instructions)}</p>`)}<small>${h(x.access_session.notice)} Session expires ${new Date(x.access_session.expires_at).toLocaleTimeString()}.</small><button class="primary accept-referral" data-id="${h(x.referral.referral_id)}">Accept referral</button></div>`}
$('#accessReferralForm').onsubmit=async e=>{e.preventDefault();let payload={patient_code:$('#accessPatientCode').value,access_code:$('#accessReferralCode').value,access_reason:$('#accessReason').value};let r=await api('/api/v1/care-network/referrals/access',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok){$('#sharedCareRecord').innerHTML=`<div class="notice">${h(await responseMessage(r,'Referral could not be verified'))}</div>`;return}let x=await r.json();$('#sharedCareRecord').innerHTML=referralPacketHtml(x);$('.accept-referral').onclick=()=>updateNetworkReferral(x.referral.referral_id,'accepted','Referral accepted by receiving facility')};
$('#emergencyAccess').onclick=async()=>{let payload={patient_code:$('#accessPatientCode').value,access_reason:$('#emergencyReason').value,emergency_confirmed:$('#emergencyConfirmed').checked};if(!confirm('Emergency access is audited and reviewed. Continue?'))return;let r=await api('/api/v1/care-network/referrals/emergency-access',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok){$('#sharedCareRecord').innerHTML=`<div class="notice">${h(await responseMessage(r,'Emergency access was not granted'))}</div>`;return}let x=await r.json();$('#sharedCareRecord').innerHTML=referralPacketHtml(x);$('.accept-referral').onclick=()=>updateNetworkReferral(x.referral.referral_id,'accepted','Referral accepted following emergency access');toast('Emergency access recorded in the privacy audit')};
async function loadNetworkReferrals(){let r=await api('/api/v1/care-network/referrals');if(!r.ok)return;let rows=await r.json();$('#networkReferralCards').innerHTML=rows.length?rows.map(x=>`<article class="network-referral"><div><span class="priority-badge ${h(x.urgency)}">${h(x.urgency)}</span><h4>${h(x.patient_code)}</h4><p>${h(x.source_facility)} → ${h(x.destination_facility)}</p></div><div><b>${careStatus(x.status)}</b><p>${h(x.reason)}</p></div><div class="referral-actions">${x.status==='accepted'?`<button data-id="${h(x.referral_id)}" data-status="arrived">Mark arrived</button>`:''}${x.status==='arrived'?`<button data-id="${h(x.referral_id)}" data-status="in_care">Begin care</button>`:''}${x.status==='in_care'?`<button data-id="${h(x.referral_id)}" data-status="completed">Complete & feedback</button>`:''}</div></article>`).join(''):'<p class="muted">No network referrals for this facility.</p>';$$('.referral-actions button').forEach(b=>b.onclick=()=>{let details=b.dataset.status==='completed'?prompt('Enter completion feedback for the referring facility'):'';if(b.dataset.status==='completed'&&!details)return;updateNetworkReferral(b.dataset.id,b.dataset.status,details)})}
$('#refreshNetworkReferrals').onclick=loadNetworkReferrals;
async function updateNetworkReferral(id,status,details){let r=await api(`/api/v1/care-network/referrals/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status,details})});if(!r.ok)return toast(await responseMessage(r,'Could not update referral'));toast(`Referral ${careStatus(status)}`);loadNetworkReferrals();loadCareNetwork()}
